image.asymptote:
// 3-D interactive (WebGL) figure.
import graph3;
size(8.5cm);
currentprojection=orthographic(5,3,2.4);
real a=2;
path3 helix=graph(new triple(real t){return (a*cos(t), a*sin(t), t/3);}, 0, 3.5pi, 220, operator ..);
draw(helix, blue+linewidth(1.1pt));
draw(circle((0,0,0), a, (0,0,1)), gray(0.6)+dashed);
real t0=1.2; triple P=(a*cos(t0), a*sin(t0), t0/3);
triple v=(-a*sin(t0), a*cos(t0), 1.0/3);
dot(P); label("$P$", P, SW);
draw(P--(P+v), red+linewidth(1.3pt), Arrow3); label("$\mathbf r'(t)$", P+v, N);
draw(O--(3,0,0),gray,Arrow3); draw(O--(0,3,0),gray,Arrow3); draw(O--(0,0,4.2),gray,Arrow3);
label("$x$",(3,0,0),S); label("$y$",(0,3,0),E); label("$z$",(0,0,4.2),N);

subsection.p:
For motion, the theorem says:
\boxed{\int_a^b \mathbf v(t)\,dt=\mathbf r(b)-\mathbf r(a).}
The integral of velocity is displacement.

image.asymptote:
import graph3;
size(11cm);
currentprojection=orthographic(7,1,3.8);
real extent=1.65;
surface cone=surface(new triple(pair q) {
  return (q.x*cos(q.y),q.x*sin(q.y),q.x);
},(-extent,0),(extent,2pi),24,48);
draw(cone,rgb(0.75,0.84,0.91)+opacity(0.38),
     meshpen=gray(0.6)+opacity(0.45)+linewidth(0.12pt));
real t0=pi/4, s0=1;
path3 generator=graph(new triple(real s) {
  return (s*cos(t0),s*sin(t0),s);
},-extent,extent,2);
draw(generator,blue+linewidth(1.2pt));
path3 ring=graph(new triple(real t) {
  return (s0*cos(t),s0*sin(t),s0);
},0,2pi,120,operator ..);
draw(ring,orange+linewidth(1.2pt));
triple P=(s0*cos(t0),s0*sin(t0),s0);
triple v=(cos(t0),sin(t0),1);
triple w=(-s0*sin(t0),s0*cos(t0),0);
triple n=(-s0*cos(t0),-s0*sin(t0),s0);
draw(P--(P+0.6v),blue+linewidth(1.2pt),Arrow3);
draw(P--(P+0.75w),orange+linewidth(1.2pt),Arrow3);
draw(P--(P+0.75n),deepgreen+linewidth(1.2pt),Arrow3);
dot(P,black+4bp); label("$P$",P,SE);
label("$\mathbf v$",P+0.6v,NE);
label("$\mathbf w$",P+0.75w,E);
label("$\mathbf N$",P+0.75n,NW);
dot(O,red+6bp); label("$O$: nonregular",O,W);
draw((0,0,-1.9)--(0,0,2.2),gray+linewidth(0.5pt),Arrow3);
label("$z$",(0,0,2.2),N);
